import { Meta, StoryObj } from "@storybook/react";
import { BLOCKS, Document } from "@contentful/rich-text-types";
import { documentToReactComponents } from "@contentful/rich-text-react-renderer";
import { BLACK_WEEK_TRANSLATION_KEY, printCustomForBlackWeek } from "./black-week";
import { initLabels } from "@/core/labels/i18n";
import { LabelType } from "@/core/labels/label-type";
import { useEffect } from "react";

type Args = {
  richText: Document;
  blackWeekKeyword: string;
};

const meta = {
  title: "Primitives/Rich Text/Black Week Override",
  render: function StoryComponent(args) {
    // The translated keyword is not mandatory, but it is made available in case the editors want to pin-point where the styling should apply.
    useEffect(() => {
      initLabels("sv", {
        sv: { [BLACK_WEEK_TRANSLATION_KEY]: args.blackWeekKeyword } as unknown as LabelType,
        en: { [BLACK_WEEK_TRANSLATION_KEY]: args.blackWeekKeyword } as unknown as LabelType,
        nn: { [BLACK_WEEK_TRANSLATION_KEY]: args.blackWeekKeyword } as unknown as LabelType,
      });
    }, [args.blackWeekKeyword]);

    // This is the main change needed to make the override work. Of course, we need to do it in the RichText component instead of here.
    const elements = documentToReactComponents(args.richText, {
      renderNode: {
        [BLOCKS.HEADING_1]: printCustomForBlackWeek("h1"),
        [BLOCKS.HEADING_2]: printCustomForBlackWeek("h2"),
        [BLOCKS.HEADING_3]: printCustomForBlackWeek("h3"),
        [BLOCKS.HEADING_4]: printCustomForBlackWeek("h4"),
        [BLOCKS.HEADING_5]: printCustomForBlackWeek("h5"),
        [BLOCKS.HEADING_6]: printCustomForBlackWeek("h6"),
      },
    });
    return <>{elements}</>;
  },
} satisfies Meta<Args>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Primary: Story = {
  args: {
    richText: {
      data: {},
      content: [
        {
          data: {},
          content: [{ data: {}, marks: [], value: "Welcome to Black Week!", nodeType: "text" }],
          nodeType: BLOCKS.HEADING_3,
        },
        {
          data: {},
          content: [
            {
              data: {},
              marks: [],
              value:
                "Here is some body text. This will not get Black Week styling even if it contains the keyword, because this is not a heading.",
              nodeType: "text",
            },
          ],
          nodeType: BLOCKS.PARAGRAPH,
        },
      ],
      nodeType: BLOCKS.DOCUMENT,
    },
    blackWeekKeyword: "Black Week",
  },
};
