import styles from "./black-week.module.less";
import { NodeRenderer } from "@contentful/rich-text-react-renderer";
import { Block, Inline } from "@contentful/rich-text-types";
import { useTranslation } from "react-i18next";

export const BLACK_WEEK_TRANSLATION_KEY = "blackWeekKeyword";

function getAllTexts(node: Block | Inline): string {
  return (
    node.content
      // this type declaration should not be necessary, but VS Code was complaining about type inference
      .map((item: (typeof node.content)[number]) => {
        if (item.nodeType === "text") {
          return item.value;
        }
        return getAllTexts(item);
      })
      .join("")
  );
}

export const printCustomForBlackWeek = (ComponentType: "h1" | "h2" | "h3" | "h4" | "h5" | "h6"): NodeRenderer =>
  function BlackWeekHeadingElement(node, next) {
    const { t } = useTranslation();

    const blackWeekKeyword = t(BLACK_WEEK_TRANSLATION_KEY, "Black Week").toLocaleLowerCase();
    const text = getAllTexts(node).toLocaleLowerCase();
    const className = text.includes(blackWeekKeyword) ? styles.blackWeekCustom : undefined;

    return <ComponentType className={className}>{next}</ComponentType>;
  };
